#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5

banner "Hawlak live demo setup"

stage "Connect Meta WhatsApp"
open_url "https://developers.facebook.com/apps/"
step "Create a Business app or choose the WhatsApp customer-connection use case."
step "Add WhatsApp and test the free Meta number with a verified synthetic recipient."
step "Add the Telnyx number. Receive the one-time SMS through its temporary messaging webhook."
step "Register the number with the API version shown in Meta. Store the six-digit PIN in a password manager, not this file."
step "Create an admin system user and generate a permanent token with WhatsApp messaging and management permissions."
ask META_GRAPH_API_VERSION "Enter the Graph API version shown by Meta (for example v24.0):"
ask WHATSAPP_PHONE_NUMBER_ID "Paste the WhatsApp Phone Number ID:"
ask_secret WHATSAPP_ACCESS_TOKEN "Paste the permanent system-user access token:"
ask_secret META_APP_SECRET "Paste the Meta app secret:"
if _existing WHATSAPP_VERIFY_TOKEN >/dev/null 2>&1; then
  WHATSAPP_VERIFY_TOKEN=$(_existing WHATSAPP_VERIFY_TOKEN)
else
  WHATSAPP_VERIFY_TOKEN=$(openssl rand -hex 24)
fi
write_env META_GRAPH_API_VERSION "$META_GRAPH_API_VERSION"
write_env WHATSAPP_PHONE_NUMBER_ID "$WHATSAPP_PHONE_NUMBER_ID"
write_env WHATSAPP_ACCESS_TOKEN "$WHATSAPP_ACCESS_TOKEN"
write_env META_APP_SECRET "$META_APP_SECRET"
write_env WHATSAPP_VERIFY_TOKEN "$WHATSAPP_VERIFY_TOKEN"
write_env WHATSAPP_PROVIDER "meta"
warn "Add a payment method and approve the utility templates before a real outbound rehearsal."
warn "Before dispatch, send START from the synthetic recipient to open the customer-service window."

stage "Create the LiveKit project"
open_url "https://cloud.livekit.io/"
step "Create or open the Hawlak demo project."
step "Copy the project WebSocket URL, API key, and API secret."
ask LIVEKIT_URL "Paste the LiveKit URL (wss://...):"
ask LIVEKIT_API_KEY "Paste the LiveKit API key:"
ask_secret LIVEKIT_API_SECRET "Paste the LiveKit API secret:"
write_env LIVEKIT_URL "$LIVEKIT_URL"
write_env LIVEKIT_API_KEY "$LIVEKIT_API_KEY"
write_env LIVEKIT_API_SECRET "$LIVEKIT_API_SECRET"

stage "Connect Telnyx telephony"
open_url "https://docs.livekit.io/telephony/start/providers/telnyx/"
step "In a paid Telnyx account, buy the test caller number."
step "Create an outbound voice profile and a credential-authenticated FQDN connection."
step "Use +E.164 number format and the current LiveKit Telnyx header instructions."
step "In LiveKit, create the outbound trunk with sip.telnyx.com and the Telnyx credentials."
ask LIVEKIT_SIP_OUTBOUND_TRUNK_ID "Paste the LiveKit outbound trunk ID:"
write_env LIVEKIT_SIP_OUTBOUND_TRUNK_ID "$LIVEKIT_SIP_OUTBOUND_TRUNK_ID"
write_env HAWLAK_AGENT_NAME "hawlak-follow-up"
write_env HAWLAK_AGENT_MODE "live"
warn "Rehearse SIP transfer. A completed outbound call does not prove REFER works."

stage "Save the speech providers"
open_url "https://platform.openai.com/api-keys"
ask_secret OPENAI_API_KEY "Paste the OpenAI API key:"
ask OPENAI_STT_MODEL "Enter the available speech-to-text model ID:"
ask OPENAI_LLM_MODEL "Enter the available conversation model ID:"
ask OPENAI_CLASSIFIER_MODEL "Enter the available classification model ID:"
open_url "https://elevenlabs.io/app/settings/api-keys"
ask_secret ELEVENLABS_API_KEY "Paste the ElevenLabs API key:"
ask ELEVENLABS_VOICE_ID "Paste the tested Arabic voice ID:"
ask ELEVENLABS_MODEL_ID "Enter the ElevenLabs model ID:"
write_env OPENAI_API_KEY "$OPENAI_API_KEY"
write_env OPENAI_BASE_URL "https://api.openai.com/v1"
write_env OPENAI_STT_MODEL "$OPENAI_STT_MODEL"
write_env OPENAI_LLM_MODEL "$OPENAI_LLM_MODEL"
write_env OPENAI_CLASSIFIER_MODEL "$OPENAI_CLASSIFIER_MODEL"
write_env ELEVENLABS_API_KEY "$ELEVENLABS_API_KEY"
write_env ELEVENLABS_VOICE_ID "$ELEVENLABS_VOICE_ID"
write_env ELEVENLABS_MODEL_ID "$ELEVENLABS_MODEL_ID"

stage "Prepare the public host"
open_url "https://console.cloud.google.com/compute/instances"
step "Create one Ubuntu VM with enough memory for the Docker demo stack."
step "Reserve a static IP and allow TCP ports 80 and 443."
step "Point a DNS A record to the static IP. Wait until the name resolves."
ask PUBLIC_HOSTNAME "Enter the public hostname without https:// or a path:"
write_env PUBLIC_HOSTNAME "$PUBLIC_HOSTNAME"
write_env PUBLIC_BASE_URL "https://$PUBLIC_HOSTNAME"
write_env DASHBOARD_ORIGIN "https://$PUBLIC_HOSTNAME"
write_env HAWLAK_AGENT_CONTROL_PORT "3100"
if ! _existing INTERNAL_API_TOKEN >/dev/null 2>&1; then
  write_env INTERNAL_API_TOKEN "$(openssl rand -hex 32)"
fi
if ! _existing HAWLAK_CONTROL_TOKEN >/dev/null 2>&1; then
  write_env HAWLAK_CONTROL_TOKEN "$(openssl rand -hex 32)"
fi
if ! _existing POSTGRES_PASSWORD >/dev/null 2>&1; then
  write_env POSTGRES_PASSWORD "$(openssl rand -hex 24)"
fi
say "After deployment, set the Meta callback URL to: https://$PUBLIC_HOSTNAME/webhooks/whatsapp"
say "Use the WHATSAPP_VERIFY_TOKEN value from .env and subscribe to the messages field."
pause "Press Enter after DNS resolves and the VM is ready."

finish
}

run_wizard "$@"; exit
